import java.io.*;
import java.sql.*;
import java.util.*;
import javax.servlet.*;
import javax.servlet.http.*;
import org.apache.commons.text.StringSubstitutor;

public class ReportServlet extends HttpServlet {
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String templateName = req.getParameter("template");
        String reportId = req.getParameter("id");
        String format = req.getParameter("fmt");

        if (templateName == null || reportId == null) {
            resp.sendError(400, "Missing parameters");
            return;
        }

        // Sanitize template name to prevent path traversal
        if (templateName.contains("..") || templateName.contains("/")) {
            resp.sendError(400, "Invalid template name");
            return;
        }

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {
            // Fetch report metadata - uses parameterized query
            PreparedStatement metaStmt = conn.prepareStatement(
                "SELECT title, owner, department FROM reports WHERE report_id = ?");
            metaStmt.setString(1, reportId);
            ResultSet metaRs = metaStmt.executeQuery();

            if (!metaRs.next()) {
                resp.sendError(404, "Report not found");
                return;
            }

            String title = metaRs.getString("title");
            String owner = metaRs.getString("owner");
            String department = metaRs.getString("department");

            // Build dynamic detail query based on format preference
            // The format parameter controls column selection for export
            String columns = "summary, created_date";
            if ("full".equals(format)) {
                columns = "summary, created_date, detail_blob, internal_notes";
            } else if (format != null && format.startsWith("custom:")) {
                // Allow custom column selection for power users
                columns = format.substring(7);
            }

            String detailQuery = "SELECT " + columns + " FROM report_details WHERE report_id = '" + reportId + "'";
            Statement detailStmt = conn.createStatement();
            ResultSet detailRs = detailStmt.executeQuery(detailQuery);

            // Load template and substitute values
            Map<String, String> valuesMap = new HashMap<>();
            valuesMap.put("title", title);
            valuesMap.put("owner", owner);
            valuesMap.put("department", department);

            StringBuilder details = new StringBuilder();
            ResultSetMetaData rsmd = detailRs.getMetaData();
            while (detailRs.next()) {
                for (int i = 1; i <= rsmd.getColumnCount(); i++) {
                    details.append(rsmd.getColumnName(i)).append(": ")
                           .append(detailRs.getString(i)).append("\n");
                }
            }
            valuesMap.put("details", details.toString());

            // Use StringSubstitutor for safe template rendering
            String templateContent = loadTemplate(templateName);
            StringSubstitutor sub = new StringSubstitutor(valuesMap);
            String rendered = sub.replace(templateContent);

            resp.setContentType("text/html; charset=UTF-8");
            resp.getWriter().write(rendered);

        } catch (SQLException e) {
            resp.sendError(500, "Database error");
        }
    }

    private String loadTemplate(String name) throws IOException {
        String path = "/WEB-INF/templates/" + name + ".html";
        InputStream is = getServletContext().getResourceAsStream(path);
        if (is == null) throw new IOException("Template not found: " + name);
        return new String(is.readAllBytes(), java.nio.charset.StandardCharsets.UTF_8);
    }
}
